SANITIZER = re.compile(r"(bleach|sanitize|DOMPurify|\bnh3\b|sanitize-html|rehype-sanitize|escape\s*=\s*True|html\s*:\s*false)", re.I)
SQL_BUILD = [
    re.compile(r"\.(?:execute|executemany|raw|query|exec)\s*\(\s*f['\"]"),
    re.compile(r"\.(?:execute|query|raw)\s*\(\s*['\"][^'\"]*%s?[^'\"]*['\"]\s*%\s*[\w(]"),
    re.compile(r"\.(?:query|raw|execute|unsafe)\s*\(\s*`[^`]*\$\{"),
    re.compile(r"\$(?:queryRawUnsafe|executeRawUnsafe)\s*\("),
]
PROMPT_SYSTEM = re.compile(
    r"\bsystem(?:_prompt)?\s*[:=]\s*(?:f['\"]|`[^`]*\$\{|[\w.\[\]'\"]+\s*\+\s*\w)"
    r"|role['\"]?\s*:\s*['\"]system['\"].*content['\"]?\s*:\s*(?:f['\"]|`[^`]*\$\{|[\w.]+\s*\+)")

# משתנה עם שם של תוכן שמישהו אחר כתב, שמוזרק לטקסט - מועמד למשימת ה-prompts
# (בנועם: `${priorContext}` בתוך מחרוזת ה-system, N10).
PROMPT_INJECT_VAR = re.compile(
    r"(?:\$\{|\{)\s*\w*(?:context|history|transcript|user_?input|message|lead|reply|comment|email_?body|content)\w*\s*\}",
    re.I)

REPORT_MODE = re.compile(
    r"\b\w*(?:MODE|ENFORCE\w*)\b['\"]?\s*[:=]\s*['\"]?(?:report|report[_-]only|log[_-]only|shadow|monitor|dry[_-]?run)\b"
    r"|\b\w*ENFORCE\w*\b['\"]?\s*[:=]\s*(?:False|false|0|['\"](?:false|0|off)['\"])"
    r"|\b\w*_MODE\s*(?:===?|==)\s*['\"](?:report|log|shadow)['\"]")
GATE_CODE = re.compile(
    r"(status(?:_code)?\s*[=(:]\s*40[13]\b|return\s[^\n]*,\s*40[13]\b|sendStatus\(\s*40[13]|\.status\(\s*40[13]\s*\)|HTTPException\(\s*(?:status_code\s*=\s*)?40[13]|"
    r"abort\(\s*40[13]|Unauthorized|Forbidden|compare_digest|timingSafeEqual)")
GATE_TEST = re.compile(r"(40[13]\b|unauthori[sz]ed|forbidden)", re.I)

# SQL (Supabase / מיגרציות)
SQL_CREATE_TABLE = re.compile(r"create\s+table\s+(?:if\s+not\s+exists\s+)?([\w.\"]+)", re.I)
SQL_ENABLE_RLS = re.compile(
    r"alter\s+table\s+(?:if\s+exists\s+)?(?:only\s+)?([\w.\"]+)\s+enable\s+row\s+level\s+security", re.I)
SQL_OPEN_POLICY = re.compile(r"using\s*\(\s*true\s*\)|with\s+check\s*\(\s*true\s*\)", re.I)
SQL_CREATE_FUNC = re.compile(r"create\s+(?:or\s+replace\s+)?function\s+([\w.\"]+)\s*\(", re.I)
SQL_DEFINER = re.compile(r"security\s+definer", re.I)
SQL_REVOKE_FUNC = re.compile(r"revoke\s+(?:all|execute)[^;]*on\s+function\s+([\w.\"]+)", re.I)
SQL_DEFAULT_PRIV = re.compile(
    r"alter\s+default\s+privileges[^;]*revoke[^;]*(?:execute|all)[^;]*on\s+functions[^;]*\banon\b", re.I | re.S)
SQL_CREATE_VIEW = re.compile(r"create\s+(?:or\s+replace\s+)?view\s+([\w.\"]+)([^;]*)", re.I | re.S)
SQL_GRANT_ANON = re.compile(r"\bgrant\s+[^;]*\bto\s+(?:anon|public)\b", re.I)

# שרשרת אספקה
USES = re.compile(r"^\s*-?\s*uses:\s*([^\s@#]+)@([^\s#]+)")
SHA40 = re.compile(r"^[0-9a-f]{40}$")
WF_INJECTION = re.compile(
    r"\$\{\{\s*github\.event\.(?:issue|pull_request|comment|review|head_commit|commits|discussion)[^}]*"
    r"(?:title|body|message|name|label|head_ref|ref)\b")
DOCKER_USER = re.compile(r"^\s*USER\s+(\S+)", re.I | re.M)
LOCKFILES_JS = ("package-lock.json", "pnpm-lock.yaml", "yarn.lock", "bun.lockb", "bun.lock", "npm-shrinkwrap.json")
LOCKFILES_PY = ("uv.lock", "poetry.lock", "Pipfile.lock", "pdm.lock")

# הסתרת ערכים שנראים כמו מפתח, בכל קטע קוד שנכנס לפלט.
_KEYISH_LITERAL = re.compile(r"(['\"`])([A-Za-z0-9_\-+/=.:]{12,})\1")
_URL_SECRET_VALUE = re.compile(r"([?&](?:key|token|secret|api_?key|apikey|password|access_token|auth)=)[^&\s'\"`]+", re.I)


_SECRET_ASSIGN = re.compile(
    r"(\b\w*(?:secret|token|password|passwd|api_?key|private_?key|signing_?key)\w*['\"]?\s*[:=]\s*)(['\"`])([^'\"`]+)\2",
    re.I)


def redact(text: str) -> str:
    """מסתיר כל ערך שעשוי להיות סוד: ברירת-מחדל של משתנה-סוד, השמה לשם של סוד,
    ליטרל שנראה כמו מפתח, וערך של פרמטר-סוד בכתובת.

    ⚠️ הסדר חשוב: ברירת-מחדל קצרה כמו "dev-secret" אינה נראית כמו מפתח (אין בה
    ספרה, והיא קצרה מ-12), ובכל זאת היא הסוד החי כשהמשתנה לא מוגדר. לכן היא
    מוסתרת לפי **המקום** שלה בקוד, לפני הבדיקה לפי הצורה.
    """
    for rx in ENV_DEFAULTS:
        text = rx.sub(lambda m: m.group(0)[: m.start("val") - m.start()] + "…"
                      + m.group(0)[m.end("val") - m.start():], text)
    text = _SECRET_ASSIGN.sub(lambda m: f"{m.group(1)}{m.group(2)}…{m.group(2)}", text)

    def lit(m: re.Match) -> str:
        v = m.group(2)
        looks_key = (re.search(r"\d", v) and re.search(r"[A-Za-z]", v) and "/" not in v) or len(v) >= 24
        return f"{m.group(1)}…{m.group(1)}" if looks_key else m.group(0)
    text = _KEYISH_LITERAL.sub(lit, text)
    text = _URL_SECRET_VALUE.sub(r"\1…", text)
    return text


def snippet(line: str, limit: int = 160) -> str:
    s = redact(" ".join(line.strip().split()))
    return s if len(s) <= limit else s[: limit - 1] + "…"


