@dataclass
class Finding:
    detector: str
    family: str
    item: str
    severity: str
    confidence: str
    title: str
    file: str = ""
    line: int = 0
    evidence: str = ""
    fix: str = ""
    probe: str = ""
    key: str = ""
    source: str = "engine"

    def finalize(self, raw_line: str = "") -> "Finding":
        basis = " ".join(raw_line.split()) or self.title
        h = hashlib.sha1(basis.encode("utf-8", "replace")).hexdigest()[:10]
        self.key = f"{self.detector}|{self.file}|{h}"
        return self


@dataclass
class Task:
    id: str
    family: str
    items: list
    question: str
    why: str
    candidates: list = field(default_factory=list)
    status: str = "ממתין"


class Project:
    def __init__(self, root: str):
        self.root = os.path.abspath(root)
        self.name = ""
        self.git_top = ""
        self.git: dict = {"is_repo": False}
        self._text: dict[str, list[str] | None] = {}
        self.files: list[str] = []
        self.tracked: set[str] = set()
        self.ignore_globs: list[str] = []
        self.warnings: list[str] = []

    # ---- git ----
    def _git(self, *args: str, cwd: str | None = None) -> tuple[int, str]:
        try:
            p = subprocess.run(["git", "-C", cwd or self.root, *args], capture_output=True,
                               text=True, timeout=60)
            return p.returncode, p.stdout
        except (OSError, subprocess.TimeoutExpired):
            return 1, ""

    def load(self) -> None:
        rc, top = self._git("rev-parse", "--show-toplevel")
        if rc == 0 and top.strip():
            self.git_top = top.strip()
            _, commit = self._git("rev-parse", "HEAD")
            _, branch = self._git("rev-parse", "--abbrev-ref", "HEAD")
            _, remote = self._git("remote", "get-url", "origin")
            _, dirty = self._git("status", "--porcelain")
            remote = re.sub(r"//[^/@]+@", "//", remote.strip())   # בלי אישורים בכתובת
            self.git = {"is_repo": True, "commit": commit.strip()[:12], "branch": branch.strip(),
                        "remote": remote, "dirty": bool(dirty.strip()),
                        "subdir": os.path.relpath(self.root, self.git_top)}
        self.name = os.path.basename(self.git_top if self.git_top and self.git.get("subdir") == "." else self.root)
        self.ignore_globs = self._ignore_patterns()
        if self.git["is_repo"]:
            _, out = self._git("ls-files", "-z", "--cached", "--others", "--exclude-standard")
            _, tracked = self._git("ls-files", "-z", "--cached")
            self.tracked = {p for p in tracked.split("\0") if p}
            files = [p for p in out.split("\0") if p]
        else:
            files = []
            for dp, dns, fns in os.walk(self.root):
                dns[:] = [d for d in dns if d not in SKIP_DIRS]
                for fn in fns:
                    files.append(os.path.relpath(os.path.join(dp, fn), self.root))
        keep = []
        for rel in files:
            rel = rel.replace(os.sep, "/")
            parts = rel.split("/")
            if any(p in SKIP_DIRS for p in parts[:-1]):
                continue
            if self._ignored(rel):
                continue
            if not os.path.isfile(os.path.join(self.root, rel)):
                continue
            keep.append(rel)
        self.files = sorted(set(keep))

    def _ignore_patterns(self) -> list[str]:
        pats = []
        for fn in (".security-audit-ignore", ".semgrepignore"):
            p = os.path.join(self.root, fn)
            if os.path.isfile(p):
                with open(p, encoding="utf-8", errors="replace") as f:
                    for ln in f:
                        ln = ln.strip()
                        if ln and not ln.startswith("#") and not ln.startswith("!"):
                            pats.append(ln)
        return pats

    def _ignored(self, rel: str) -> bool:
        for pat in self.ignore_globs:
            p = pat.lstrip("/")
            if p.endswith("/"):
                if rel.startswith(p) or f"/{p}" in f"/{rel}":
                    return True
                continue
            if fnmatch.fnmatch(rel, p) or fnmatch.fnmatch(os.path.basename(rel), p):
                return True
            if "/" not in p and ("/" + p + "/") in ("/" + rel):
                return True
            if fnmatch.fnmatch(rel, p.rstrip("/") + "/*") or fnmatch.fnmatch(rel, "*/" + p):
                return True
        return False

    # ---- קריאה ----
    def lines(self, rel: str) -> list[str] | None:
        if rel in self._text:
            return self._text[rel]
        path = os.path.join(self.root, rel)
        out: list[str] | None = None
        try:
            if os.path.getsize(path) <= MAX_FILE_BYTES:
                with open(path, "rb") as f:
                    raw = f.read()
                if b"\0" not in raw[:4096]:
                    text = raw.decode("utf-8", "replace")
                    ls = text.splitlines()
                    if not any(FILE_IGNORE in x for x in ls[:5]):
                        out = ls
        except OSError:
            out = None
        self._text[rel] = out
        return out

    def text(self, rel: str) -> str:
        ls = self.lines(rel)
        return "\n".join(ls) if ls else ""

    def ext(self, rel: str) -> str:
        return os.path.splitext(rel)[1].lower()

    def code_files(self, include_tests: bool = False) -> list[str]:
        out = []
        for rel in self.files:
            if self.ext(rel) not in CODE_EXT or rel.endswith(".min.js"):
                continue
            if not include_tests and TEST_PATH.search(rel):
                continue
            out.append(rel)
        return out

    def iter_lines(self, files: list[str]):
        for rel in files:
            ls = self.lines(rel)
            if not ls:
                continue
            for i, ln in enumerate(ls, 1):
                if len(ln) > MAX_LINE_CHARS or LINE_IGNORE in ln:
                    continue
                # שורת הערה אינה אוכפת ואינה חושפת - היא רק מתארת. (בלי זה, קוד שמתעד
                # את הדפוס המסוכן, כמו skill-router-guard.py, מדווח כאילו הוא מבצע אותו.)
                if ln.lstrip().startswith(("#", "//", "/*", "* ", "<!--")) and not ln.startswith("#!"):
                    continue
                if "re.compile(" in ln or "new RegExp(" in ln:
                    continue   # הגדרת דפוס-גלאי אינה הקוד שהוא מחפש
                yield rel, i, ln


# --------------------------------------------------------------------------
# גלאים מכניים. כל גלאי מחזיר ממצאים, ונרשם ב-DETECTORS עם מה שהוא בודק -
# כדי ש"נבדק ונמצא תקין" יופיע בדוח גם כשאין ממצא.
# --------------------------------------------------------------------------

def _f(det, fam, item, sev, conf, title, rel, line_no, raw, fix, probe="") -> Finding:
    return Finding(det, fam, item, sev, conf, title, rel, line_no, snippet(raw), fix, probe).finalize(raw)


# TOKEN הוא גם "טוקן של מודל": STORIES_VISION_MAX_TOKENS ו-TIKTOK_MAX_WORDS_TOKEN_MATCH
# סומנו בהרצה הראשונה על sales-automation ו-aimprove-manychat-bot. שם של מגבלה או ספירה,
# או ערך שהוא מספר או בוליאני, אינו סוד.
_NOT_SECRET_NAME = re.compile(r"MAX|MIN|LIMIT|COUNT|TOKENS\b|_TOKENS_|BUDGET|WINDOW|TTL|EXPIR|LENGTH|SIZE|MATCH|"
                              r"TIMEOUT|RETRIES|_URL\b|_URI\b|_PATH\b|_HEADER\b|_NAME\b|_FILE\b|_DIR\b", re.I)
_NOT_SECRET_VALUE = re.compile(r"^(?:-?\d+(?:\.\d+)?|true|false|yes|no|on|off)$", re.I)


def d_env_default(p: Project) -> list[Finding]:
    out = []
    for rel, i, ln in p.iter_lines(p.code_files()):
        for rx in ENV_DEFAULTS:
            m = rx.search(ln)
            if not m:
                continue
            name, default = m.group("name"), m.group("val")
            if not default.strip() or default.strip() in ("None", "null", "undefined"):
                continue
            if _NOT_SECRET_NAME.search(name) or _NOT_SECRET_VALUE.match(default.strip()):
                continue
            ev = f"{name} ← ברירת מחדל כתובה בקוד ({len(default)} תווים, הערך מוסתר)"
            f = Finding("env-default-secret", "ב", "B2", "high", CONF_CERTAIN,
                        f"הסוד {name} נופל לערך שכתוב בקוד כשהמשתנה לא מוגדר", rel, i, ev,
                        "לקרוא בלי ערך ברירת-מחדל, ולהפיל את השירות בהפעלה כשהמשתנה חסר. "
                        "לבדוק בספק האירוח שהמשתנה מוגדר בייצור - אם לא, הערך שבקוד הוא הסוד החי, "
                        "ויש להחליף אותו.")
            out.append(f.finalize(name + "|" + rel))
            break
    return out


def d_fail_open(p: Project) -> list[Finding]:
    out = []
    for rel, i, ln in p.iter_lines(p.code_files()):
        if any(rx.search(ln) for rx in FAIL_OPEN):
            out.append(_f("fail-open-gate", "א", "B2", "high", CONF_SUSPECT,
                          "שער שנראה כאילו הוא נפתח כשהסוד חסר", rel, i, ln,
                          "שתי שאלות נפרדות: קודם 'האם הסוד מוגדר' - אם לא, לסרב; רק אחר כך "
                          "'האם הוא תואם'. סוד חסר ← סירוב, לעולם לא מעבר.",
                          "לשלוח בקשה בלי הסוד ← חייב 401/403"))
    return out


def d_secret_in_url(p: Project) -> list[Finding]:
    return [_f("secret-in-url", "ב", "B1", "medium", CONF_SUSPECT,
               "סוד מוזרק לתוך כתובת (query string)", rel, i, ln,
               "להעביר את הסוד בכותרת (header) או בגוף הבקשה. כתובות נכנסות ללוגים, להיסטוריה ול-Referer.")
            for rel, i, ln in p.iter_lines(p.code_files()) if SECRET_IN_URL.search(ln)]


def d_client_secret(p: Project) -> list[Finding]:
    files = [r for r in p.files if p.ext(r) in CODE_EXT or os.path.basename(r).startswith(".env")]
    return [_f("client-exposed-secret", "ב", "B1", "high", CONF_CERTAIN,
               "משתנה עם קידומת ציבורית נושא שם של סוד - הוא נשלח לדפדפן", rel, i, ln,
               "סוד לעולם לא בקידומת NEXT_PUBLIC_/VITE_/REACT_APP_. להעביר את הקריאה לשרת.")
            for rel, i, ln in p.iter_lines(files) if CLIENT_SECRET.search(ln)]


def d_nonconst_compare(p: Project) -> list[Finding]:
    return [_f("nonconstant-compare", "ב", "B2", "low", CONF_SUSPECT,
               "השוואת סוד עם == במקום השוואה קבועת-זמן", rel, i, ln,
               "השוואה קבועת-זמן על בייטים, דרך helper אחד לריפו (hmac.compare_digest / crypto.timingSafeEqual).")
            for rel, i, ln in p.iter_lines(p.code_files()) if NONCONST_COMPARE.search(ln)]


def d_env_tracked(p: Project) -> list[Finding]:
    out = []
    if not p.git["is_repo"]:
        return out
    for rel in sorted(p.tracked):
        base = os.path.basename(rel)
        if (base == ".env" or base.startswith(".env.") or base.endswith(".env")) and not re.search(
                r"\.(example|sample|template|dist)$", base):
            out.append(Finding("env-file-tracked", "ב", "B3", "high", CONF_CERTAIN,
                               "קובץ סודות (.env) נמצא בגיט", rel, 0, base,
                               "להוציא מהגיט (git rm --cached), להוסיף ל-.gitignore, ולהחליף כל סוד "
                               "שהיה בו - הוא נשאר בהיסטוריה.").finalize(rel))
    uses_env = any(re.search(r"os\.environ|getenv|process\.env|dotenv", p.text(r))
                   for r in p.code_files()[:400])
    if uses_env:
        rc, _ = p._git("check-ignore", "-q", "--no-index", ".env", cwd=p.git_top)
        if rc != 0:
            out.append(Finding("env-not-ignored", "ב", "B3", "medium", CONF_CERTAIN,
                               "קובץ .env אינו מכוסה ב-.gitignore", ".gitignore", 0, ".env",
                               "להוסיף שורה .env ל-.gitignore לפני שנוצר קובץ כזה.").finalize(".env"))
    return out


def _route_rows(p: Project) -> list[dict]:
    """כל הנתיבים שאפשר לזהות: קובץ, שורה, שיטה, נתיב."""
    rows = []
    for rel, i, ln in p.iter_lines(p.code_files()):
        m = PY_ROUTE.search(ln)
        if m:
            kind, path, rest = m.group(1), m.group(2), m.group(3)
            if kind in ("route", "api_route"):
                ms = re.findall(r"['\"](GET|POST|PUT|PATCH|DELETE)['\"]", rest, re.I)
                methods = [x.upper() for x in ms] or ["GET"]
            else:
                methods = [kind.upper()]
            rows.append({"file": rel, "line": i, "methods": methods, "path": path, "raw": ln})
            continue
        m = JS_ROUTE.search(ln)
        if m and m.group(1) != "use":
            rows.append({"file": rel, "line": i, "methods": [m.group(1).upper()], "path": m.group(2), "raw": ln})
            continue
        m = NEXT_ROUTE.search(ln)
        if m:
            path = "/" + re.sub(r"(^|/)(src/)?(app|pages)/", "", os.path.dirname(rel)).strip("/")
            rows.append({"file": rel, "line": i, "methods": [m.group(1)], "path": path, "raw": ln})
    return rows


def d_state_change_get(p: Project) -> list[Finding]:
    out = []
    for r in _route_rows(p):
        if "GET" in r["methods"] and STATE_WORDS.search(r["path"]):
            out.append(_f("state-change-get", "א", "A5", "medium", CONF_SUSPECT,
                          f"פעולה שמשנה מצב נחשפת ב-GET ({r['path']})", r["file"], r["line"], r["raw"],
                          "פעולה שמשנה מצב - רק ב-POST/DELETE עם אימות. crawler כבר הריץ purge בעבר.",
                          f"GET {r['path']} בלי אימות ← חייב 401/405"))
    return out


def _handler_region(p: Project, rel: str, line_no: int, rows: list[dict]) -> str:
    """הקוד של handler אחד בלבד - מהנתיב עד סוף הפונקציה שלו.

    בדיקה על הקובץ כולו פספסה את N1 (קריטי) בנועם: server.js של 4,000 שורות מכיל
    HMAC במקום אחר לגמרי (טופס הליד), ולכן 'יש חתימה בקובץ' היה נכון - ולא רלוונטי.
    הסוף: השורה הראשונה שמתחילה בעמודה 0 אחרי גוף מוזח (בפייתון: אחרי ה-def; ב-JS:
    כולל ה-`});` הסוגר), לכל היותר 150 שורות, ולעולם לא מעבר לנתיב הבא.
    """
    ls = p.lines(rel) or []
    nxt = [r["line"] for r in rows if r["file"] == rel and r["line"] > line_no]
    hard_end = min(min(nxt) - 1 if nxt else len(ls), line_no + 150)
    out = [ls[line_no - 1]]
    i = line_no
    while i < hard_end and re.match(r"(?:@|def |async def )", ls[i]):   # שאר הדקורטורים וה-def
        out.append(ls[i])
        i += 1
    while i < hard_end:
        ln = ls[i]
        if ln.strip() and not ln[:1].isspace():
            if ln.lstrip().startswith(("}", ")")):
                out.append(ln)
            break
        out.append(ln)
        i += 1
    return "\n".join(out)


def d_webhook_signature(p: Project) -> list[Finding]:
    out = []
    rows = _route_rows(p)
    for r in rows:
        # לפי הנתיב בלבד. "כל POST בקובץ ששמו webhook_server.py" סימן גם דף הסרה ומסך חייגן
        # ב-sales-automation (23-09) - נתיבים שאינם webhook ויש להם אימות משלהם.
        if not re.search(r"hook", r["path"], re.I) or "POST" not in r["methods"] and "ALL" not in r["methods"]:
            continue
        text = p.text(r["file"])
        # אימות שנעשה ב-middleware שמחובר לנתיב (app.use('/webhook', verify...)) - בודקים את הקובץ כולו
        mounted = re.search(r"\.use\(\s*['\"`][^'\"`]*hook[^)]*", text, re.I)
        region = _handler_region(p, r["file"], r["line"], rows)
        if SIG_TOKENS.search(region) or HANDLER_AUTH.search("\n".join(region.splitlines()[1:]) + "\n" + r["raw"]) or (
                mounted and SIG_TOKENS.search(mounted.group(0) + text)):
            continue
        out.append(_f("webhook-no-signature", "א", "E2", "high", CONF_SUSPECT,
                      f"webhook נכנס בלי שום אימות חתימה בקובץ ({r['path']})", r["file"], r["line"], r["raw"],
                      "לאמת חתימת HMAC של הספק (או סוד בכותרת, לא בכתובת), ולסרב כשהסוד חסר.",
                      f"POST {r['path']} בלי חתימה ← חייב 401"))
    return out


