def d_pii_files(p: Project) -> list[Finding]:
    out = []
    for rel in p.files:
        if p.ext(rel) not in DATA_EXT or TEST_PATH.search(rel):
            continue
        base = os.path.basename(rel)
        if base in ("package.json", "package-lock.json", "tsconfig.json", "composer.json") or base.startswith("."):
            continue
        t = p.text(rel)
        if not t:
            continue
        emails = {e.lower() for e, dom in ((m.group(0), m.group(1)) for m in EMAIL.finditer(t))
                  if not EMAIL_SAFE_DOMAINS.search(dom)}
        phones = {re.sub(r"\D", "", m.group(0))[-9:] for m in IL_PHONE.finditer(t)}
        if len(emails) + len(phones) >= 3:
            out.append(Finding("pii-data-file", "ג", "E1", "medium", CONF_SUSPECT,
                               f"קובץ נתונים עם פרטי קשר של אנשים ({len(emails)} מיילים, {len(phones)} טלפונים)",
                               rel, 0, "הערכים עצמם לא מוצגים",
                               "אם הריפו ייחשף - מי ייפגע? להוציא מהגיט (והיסטוריה) או להחליף בנתוני-דמה.")
                       .finalize(rel))
    return out


def d_error_leak(p: Project) -> list[Finding]:
    entry = {r for r in p.code_files() if ANY_ROUTE.search(p.text(r)) or BOT_HANDLER.search(p.text(r))}
    return [_f("error-leak", "ג", "E3", "low", CONF_SUSPECT,
               "הודעת שגיאה פנימית חוזרת למשתמש", rel, i, ln,
               "למשתמש - הודעה כללית; הפרטים ללוג בלבד.")
            for rel, i, ln in p.iter_lines(p.code_files())
            if ERROR_LEAK_SEND.search(ln) or ERROR_LEAK_KWARG.search(ln)
            or (rel in entry and ERROR_LEAK_RETURN.search(ln))]


def d_rate_limit(p: Project) -> list[Finding]:
    routes = _route_rows(p)
    bots = [r for r in p.code_files() if BOT_HANDLER.search(p.text(r))]
    if not routes and not bots:
        return []
    if any(RATE_LIMIT.search(p.text(r)) for r in p.code_files()):
        return []
    anchor = routes[0] if routes else {"file": bots[0], "line": 1, "raw": ""}
    return [_f("no-rate-limit", "ד", "C1", "medium", CONF_SUSPECT,
               f"יש {len(routes)} נתיבים ו-{len(bots)} בוטים, ואין שום הגבלת קצב בפרויקט",
               anchor["file"], anchor["line"], anchor.get("raw", ""),
               "הגבלת קצב (וגודל) על כל נתיב לא-מאומת שעולה כסף או ששולח משהו, ועל כל מסך התחברות.")]


# innerHTML שמקבל מחרוזת קבועה אינו פתח - אין בו תוכן של אף אחד.
