def _workflows(p: Project) -> list[str]:
    return [r for r in p.files if re.match(r"(?:.*/)?\.github/workflows/[^/]+\.ya?ml$", r)]


def d_supply_chain(p: Project) -> list[Finding]:
    out = []
    files = set(p.files)
    for rel in p.files:
        base, d = os.path.basename(rel), os.path.dirname(rel)
        sib = lambda n: (f"{d}/{n}" if d else n) in files  # noqa: E731
        if base == "package.json":
            try:
                pkg = json.loads(p.text(rel) or "{}")
            except json.JSONDecodeError:
                pkg = {}
            if (pkg.get("dependencies") or pkg.get("devDependencies")) and not any(sib(n) for n in LOCKFILES_JS):
                # lockfile בתיקיית-אב (monorepo) גם הוא נעילה
                parents = [x for x in files if os.path.basename(x) in LOCKFILES_JS and d.startswith(os.path.dirname(x))]
                if not parents:
                    out.append(Finding("lockfile-missing", "ו", "E4a", "low", CONF_CERTAIN,
                                       "package.json בלי lockfile", rel, 0, base,
                                       "להריץ install ולהכניס את ה-lockfile לגיט.").finalize(rel))
        elif re.match(r"requirements[\w.-]*\.txt$", base):
            reqs = [x.strip() for x in (p.lines(rel) or []) if x.strip() and not x.strip().startswith(("#", "-"))]
            loose = [x for x in reqs if "==" not in x and "@" not in x]
            if loose and not any(sib(n) for n in LOCKFILES_PY):
                out.append(Finding("lockfile-missing", "ו", "E4a", "low", CONF_CERTAIN,
                                   f"{len(loose)} תלויות Python בלי גרסה נעולה", rel, 0, base,
                                   "לנעול גרסאות (==) או להשתמש ב-lockfile (uv.lock/poetry.lock).").finalize(rel))
    wfs = _workflows(p)
    for rel in wfs:
        ls = p.lines(rel) or []
        text = "\n".join(ls)
        loose = [m for m in (USES.match(x) for x in ls) if m and not m.group(1).startswith("./")
                 and not SHA40.match(m.group(2))]
        if loose:
            out.append(Finding("actions-unpinned", "ו", "E4b", "low", CONF_CERTAIN,
                               f"{len(loose)} actions לא נעולים ל-SHA", rel, 0, loose[0].group(0).strip(),
                               "לנעול כל uses: ל-commit SHA מלא (Dependabot יעדכן).").finalize(rel))
        if not re.search(r"^permissions:", text, re.M):
            out.append(Finding("workflow-no-permissions", "ו", "E4b", "low", CONF_CERTAIN,
                               "workflow בלי permissions בראשו", rel, 0, "",
                               "permissions: contents: read בראש הקובץ.").finalize(rel))
        run_indent = None   # בתוך בלוק run: רב-שורתי - העומק של המפתח run
        for i, ln in enumerate(ls, 1):
            indent = len(ln) - len(ln.lstrip())
            m_run = re.match(r"^(\s*)-?\s*run:\s*(.*)$", ln)
            if m_run:
                run_indent = indent if m_run.group(2).strip() in ("|", ">", "|-", ">-", "") else None
                in_run = True
            elif run_indent is not None and (not ln.strip() or indent > run_indent):
                in_run = True
            else:
                run_indent, in_run = None, False
            if "pull_request_target" in ln:
                out.append(_f("pull-request-target", "ו", "E4b", "high", CONF_SUSPECT,
                              "pull_request_target - קוד מ-PR זר רץ עם סודות", rel, i, ln,
                              "להחליף ב-pull_request, או לא לעשות checkout לקוד ה-PR."))
            # ${{ }} בתוך env: הוא הדרך הבטוחה - רק בתוך run: זו הזרקה (virtual-office, 23-09)
            if in_run and WF_INJECTION.search(ln):
                out.append(_f("workflow-injection", "ו", "E4b", "high", CONF_SUSPECT,
                              "טקסט שזר שולט בו מוזרק לפקודת run", rel, i, ln,
                              "להעביר דרך env: ולצטט כמשתנה, לא ${{ }} בתוך run."))
    manifests = [r for r in p.files if os.path.basename(r) in ("package.json", "pyproject.toml")
                 or re.match(r"requirements[\w.-]*\.txt$", os.path.basename(r))]
    top_has = lambda path: os.path.isfile(os.path.join(p.git_top or p.root, path))  # noqa: E731
    if manifests and p.git["is_repo"]:
        if not (top_has(".github/dependabot.yml") or top_has(".github/dependabot.yaml")):
            out.append(Finding("dependabot-missing", "ו", "E4c", "low", CONF_CERTAIN,
                               "אין .github/dependabot.yml", ".github/dependabot.yml", 0, "",
                               "להעתיק את baseline/dependabot.yml.").finalize("dependabot"))
        top_wfs = []
        wdir = os.path.join(p.git_top or p.root, ".github", "workflows")
        if os.path.isdir(wdir):
            for fn in os.listdir(wdir):
                try:
                    with open(os.path.join(wdir, fn), encoding="utf-8", errors="replace") as f:
                        top_wfs.append(f.read())
                except OSError:
                    pass
        if not any(re.search(r"gitleaks|osv-scanner|semgrep|codeql", w) for w in top_wfs):
            out.append(Finding("security-ci-missing", "ו", "E4e", "low", CONF_CERTAIN,
                               "אין סריקת אבטחה ב-CI (gitleaks / osv-scanner / semgrep)",
                               ".github/workflows/", 0, "",
                               "להעתיק את baseline/security-baseline.yml.").finalize("security-ci"))
    for rel in p.files:
        if not re.match(r"Dockerfile(?:\.[\w.-]+)?$", os.path.basename(rel)):
            continue
        t = p.text(rel)
        users = DOCKER_USER.findall(t)
        if not users or users[-1].lower() in ("root", "0", "0:0"):
            out.append(Finding("docker-root", "ו", "E4d", "low", CONF_CERTAIN,
                               "הקונטיינר רץ כ-root (אין USER לא-root)", rel, 0, "",
                               "משתמש ייעודי ו-USER לפני CMD.").finalize(rel))
        d = os.path.dirname(rel)
        di = os.path.join(p.root, d, ".dockerignore")
        di_text = ""
        if os.path.isfile(di):
            with open(di, encoding="utf-8", errors="replace") as f:
                di_text = f.read()
        if not re.search(r"^\s*\**/?\.env", di_text, re.M):
            out.append(Finding("dockerignore-env", "ו", "E4d", "medium", CONF_CERTAIN,
                               ".dockerignore לא מונע כניסת .env לתמונה", rel, 0, "",
                               "להוסיף .env ו-.env.* ל-.dockerignore שליד ה-Dockerfile.").finalize(rel + "|di"))
    return out


def d_report_mode(p: Project) -> list[Finding]:
    files = [r for r in p.files if (p.ext(r) in CODE_EXT | CONFIG_EXT or os.path.basename(r).startswith(".env"))
             and not TEST_PATH.search(r) and not r.endswith(("package-lock.json", ".lock"))]
    return [_f("report-only-mode", "ז", "—", "medium", CONF_SUSPECT,
               "שער שנראה כאילו הוא במצב דיווח בלבד (לא אוכף)", rel, i, ln,
               "מצב דיווח מותר רק עם תאריך יעד ומי שאחראי להדליק. /health מדווח enforced/DISABLED.")
            for rel, i, ln in p.iter_lines(files) if REPORT_MODE.search(ln)]


def d_gates_without_tests(p: Project) -> list[Finding]:
    gates = [(rel, i, ln) for rel, i, ln in p.iter_lines(p.code_files()) if GATE_CODE.search(ln)]
    if not gates:
        return []
    tests = [r for r in p.files if TEST_PATH.search(r) and p.ext(r) in CODE_EXT]
    if any(GATE_TEST.search(p.text(t)) for t in tests):
        return []
    rel, i, ln = gates[0]
    return [_f("gates-without-tests", "ז", "—", "medium", CONF_SUSPECT,
               f"יש {len(gates)} מקומות שדוחים גישה, ואף בדיקה לא מוודאת שהם דוחים", rel, i, ln,
               "לכל שער: בדיקה ששולחת בקשה בלי הרשאה ומצפה ל-401/403 - ולראות אותה נופלת כשמסירים את השער.")]


