# --------------------------------------------------------------------------
# כלים חיצוניים - שלושת הסורקים שכבר רצים ב-CI (security-baseline.yml).
# לא מותקן / נכשל ← "לא נבדק", לעולם לא "תקין".
# --------------------------------------------------------------------------

def _run(cmd: list[str], timeout: int, cwd: str | None = None) -> tuple[int, str, str]:
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, cwd=cwd)
    return p.returncode, p.stdout, p.stderr


def _version(tool: str) -> str:
    try:
        rc, out, err = _run([tool, "--version"], 30)
        return (out or err).strip().splitlines()[0][:60] if rc == 0 else ""
    except (OSError, subprocess.TimeoutExpired, IndexError):
        return ""


def run_gitleaks(p: Project, history: bool) -> tuple[list[Finding], dict]:
    tool = shutil.which("gitleaks")
    if not tool:
        return [], {"ran": False, "reason": "gitleaks לא מותקן"}
    cfg = None
    for c in (os.path.join(p.git_top or p.root, ".gitleaks.toml"), os.path.expanduser("~/.githooks/gitleaks.toml")):
        if os.path.isfile(c):
            cfg = c
            break
    with tempfile.TemporaryDirectory() as td:
        rep = os.path.join(td, "gl.json")
        if history and p.git["is_repo"]:
            cmd = [tool, "git", p.git_top, "--report-format", "json", "--report-path", rep,
                   "--redact=100", "--no-banner", "--exit-code", "0"]
            mode = "היסטוריה מלאה"
        else:
            cmd = [tool, "dir", p.root, "--report-format", "json", "--report-path", rep,
                   "--redact=100", "--no-banner", "--exit-code", "0"]
            mode = "הקבצים של היום"
        ign = os.path.join(p.git_top or p.root, ".gitleaksignore")
        if os.path.isfile(ign):
            cmd += ["--gitleaks-ignore-path", ign]
        if cfg:
            cmd += ["--config", cfg]
        try:
            rc, _, err = _run(cmd, 900)
        except subprocess.TimeoutExpired:
            return [], {"ran": False, "reason": "gitleaks חרג מזמן הריצה"}
        if rc != 0 or not os.path.isfile(rep):
            return [], {"ran": False, "reason": f"gitleaks נכשל (קוד {rc})"}
        try:
            with open(rep, encoding="utf-8") as f:
                rows = json.load(f) or []
        except (OSError, json.JSONDecodeError):
            return [], {"ran": False, "reason": "gitleaks: דוח לא קריא"}
    wanted = set(p.files)
    out = []
    for r in rows:
        path = r.get("File", "")
        rel = os.path.relpath(path, p.root) if os.path.isabs(path) else path
        if history:
            rel = os.path.relpath(os.path.join(p.git_top, path), p.root) if p.git_top else path
        elif rel not in wanted:
            continue   # קובץ שגיט מתעלם ממנו (למשל .env מקומי) אינו ממצא
        commit = (r.get("Commit") or "")[:10]
        ev = f"כלל {r.get('RuleID', '?')}" + (f", commit {commit}" if commit else "") + " (הערך מוסתר)"
        out.append(Finding("gitleaks", "ב", "B3", "high", CONF_CERTAIN,
                           "סוד בקוד (gitleaks)" + (" - בהיסטוריה" if history else ""),
                           rel, int(r.get("StartLine") or 0), ev,
                           "להוציא מהקוד, להחליף את הסוד אצל הספק; אם הוחלט לקבל - לרשום ב-.security-accepted.json."
                           ).finalize(f"{r.get('RuleID')}|{rel}|{r.get('Fingerprint', '')}|{commit}"))
    return out, {"ran": True, "version": _version(tool), "mode": mode, "config": "מותאם" if cfg else "ברירת מחדל"}


def _osv_sev(v: dict) -> str:
    s = ((v.get("database_specific") or {}).get("severity") or "").upper()
    if s in ("CRITICAL", "HIGH"):
        return s.lower()
    if s in ("MODERATE", "MEDIUM"):
        return "medium"
    if s == "LOW":
        return "low"
    return "medium"


def run_osv(p: Project) -> tuple[list[Finding], dict]:
    tool = shutil.which("osv-scanner")
    if not tool:
        return [], {"ran": False, "reason": "osv-scanner לא מותקן"}
    with tempfile.TemporaryDirectory() as td:
        rep = os.path.join(td, "osv.json")
        try:
            rc, _, err = _run([tool, "scan", "source", "--recursive", "--format", "json",
                               "--output-file", rep, p.root], 900)
        except subprocess.TimeoutExpired:
            return [], {"ran": False, "reason": "osv-scanner חרג מזמן הריצה"}
        # 0 = נקי, 1 = נמצאו פרצות, 128 = אין מה לסרוק. כל השאר - תקלת כלי.
        if rc == 128:
            return [], {"ran": True, "version": _version(tool), "note": "לא נמצאו קובצי תלויות"}
        if rc not in (0, 1) or not os.path.isfile(rep):
            return [], {"ran": False, "reason": f"osv-scanner נכשל (קוד {rc})"}
        try:
            with open(rep, encoding="utf-8") as f:
                d = json.load(f)
        except (OSError, json.JSONDecodeError):
            return [], {"ran": False, "reason": "osv-scanner: דוח לא קריא"}
    out = []
    for res in d.get("results", []):
        src = res.get("source", {}).get("path", "")
        rel = os.path.relpath(src, p.root) if os.path.isabs(src) else src
        for pk in res.get("packages", []):
            vulns = pk.get("vulnerabilities", [])
            if not vulns:
                continue
            sev = min((_osv_sev(v) for v in vulns), key=lambda s: SEV_RANK[s])
            name, ver = pk["package"].get("name"), pk["package"].get("version")
            ids = sorted({v.get("id") for v in vulns})
            out.append(Finding("osv", "ו", "E4", sev, CONF_CERTAIN,
                               f"{name}@{ver}: {len(ids)} פרצות ידועות", rel, 0,
                               ", ".join(ids[:4]) + ("…" if len(ids) > 4 else ""),
                               "לעדכן לגרסה מתוקנת (Dependabot פותח PR לרוב).").finalize(f"{name}|{ver}|{rel}"))
    return out, {"ran": True, "version": _version(tool)}


def _semgrep_family(rule: str) -> str:
    r = rule.lower()
    if "secret" in r or "crypto" in r or "hash" in r or "jwt" in r:
        return "ב"
    if any(k in r for k in ("cors", "auth", "csrf", "permission")):
        return "א"
    if any(k in r for k in ("docker", "github-actions", "yaml")):
        return "ו"
    return "ה"


def run_semgrep(p: Project) -> tuple[list[Finding], dict]:
    tool = shutil.which("semgrep")
    if not tool:
        return [], {"ran": False, "reason": "semgrep לא מותקן"}
    cmd = [tool, "scan", "--config", "p/security-audit", "--config", "p/owasp-top-ten", "--config", "p/secrets",
           "--metrics=off", "--severity", "ERROR", "--json", "--quiet",
           "--exclude", "node_modules", "--exclude", ".next", "--exclude", "dist",
           "--exclude", "*.min.js", "--exclude", "*.md", p.root]
    try:
        rc, out_s, err = _run(cmd, 1200)
    except subprocess.TimeoutExpired:
        return [], {"ran": False, "reason": "semgrep חרג מזמן הריצה"}
    try:
        d = json.loads(out_s or "{}")
    except json.JSONDecodeError:
        return [], {"ran": False, "reason": f"semgrep נכשל (קוד {rc}; ייתכן שאין רשת לכללי-הרישום)"}
    if rc not in (0, 1) and not d.get("results"):
        return [], {"ran": False, "reason": f"semgrep נכשל (קוד {rc})"}
    out = []
    for r in d.get("results", []):
        path = r.get("path", "")
        rel = os.path.relpath(path, p.root) if os.path.isabs(path) else path
        rule = r.get("check_id", "?").split(".")[-1]
        out.append(Finding("semgrep", _semgrep_family(rule), "—", "medium", CONF_SUSPECT,
                           f"semgrep: {rule}", rel, int(r.get("start", {}).get("line") or 0),
                           snippet((r.get("extra") or {}).get("lines") or ""),
                           "לקרוא את הקוד ולהכריע - לפי ביקורת 09/2026 רוב ממצאי semgrep אינם פרצה.")
                   .finalize(f"{rule}|{rel}|{r.get('start', {}).get('line')}"))
    return out, {"ran": True, "version": _version(tool)}


# --------------------------------------------------------------------------
# משימות לבדיקת סוכן
# --------------------------------------------------------------------------

def _cands(rows, limit=40) -> list[dict]:
    seen, out = set(), []
    for rel, i, ln in rows:
        k = (rel, i)
        if k in seen:
            continue
        seen.add(k)
        out.append({"file": rel, "line": i, "snippet": snippet(ln)})
        if len(out) >= limit:
            break
    return out


def build_tasks(p: Project) -> list[Task]:
    tasks: list[Task] = []
    code = p.code_files()
    routes = _route_rows(p)

    id_routes = [(r["file"], r["line"], r["raw"]) for r in routes if ID_PARAM.search(r["path"] + " " + r["raw"])]
    id_lines = [(rel, i, ln) for rel, i, ln in p.iter_lines(code) if re.search(r"req\.params|request\.view_args|params\.\w*[iI]d\b", ln)]
    if id_routes or id_lines:
        tasks.append(Task("א-idor", "א", ["B4"],
                          "לכל פעולה שמקבלת מזהה מבחוץ: איפה נבדק שהמזהה הזה שייך למשתמש שקורא?",
                          "'מזוהה' אינו 'מורשה'. בסטודיו זה אפשר ביטול שיעור של תלמידה אחרת.",
                          _cands(id_routes + id_lines)))
    admin = [(r["file"], r["line"], r["raw"]) for r in routes if re.search(r"admin|dashboard|internal|manage", r["path"] + r["file"], re.I)]
    if admin:
        tasks.append(Task("א-admin", "א", ["A4", "A5"],
                          "כל נתיב ניהול: נבדקת הרשאה בצד השרת (לא רק בדפדפן)? מה רואה מי שנכנס בלי סיסמה?",
                          "'אף אחד לא יודע את הכתובת' אינה תשובה - 13 דפי ניהול היו פתוחים חצי שנה.",
                          _cands(admin)))
    hooks = [(r["file"], r["line"], r["raw"]) for r in routes if re.search(r"hook", r["path"] + r["file"], re.I)]
    bots = [(rel, 1, (p.lines(rel) or [""])[0]) for rel in code if BOT_HANDLER.search(p.text(rel))]
    if hooks or bots:
        tasks.append(Task("א-inbound", "א", ["E2", "F2"],
                          "כל webhook ובוט: האימות נאכף בפועל (לא במצב דיווח), ונכשל-סגור כשהסוד חסר? "
                          "מי יכול לשלוח לו, ומה קורה אז?",
                          "בנועם כל אדם יכול היה להזריק 'הודעת ליד' מכל מספר, והבוט ענה בשם המותג.",
                          _cands(hooks + bots)))
    secret_reads = [(rel, i, ln) for rel, i, ln in p.iter_lines(code)
                    if re.search(r"(?:os\.environ|getenv|process\.env)[^\n]*" + _SECRET_NAME, ln, re.I)]
    if secret_reads:
        tasks.append(Task("ב-secrets", "ב", ["B2", "F3"],
                          "לכל קריאת סוד: מה קורה כשהמשתנה לא מוגדר בייצור? ואילו מפתחות השירות מחזיק - "
                          "מה אפשר לעשות איתם אם הוא ייפרץ?",
                          "ב-noam-whatsapp נמדד שהמשתנים אינם מוגדרים בייצור - ברירות-המחדל בקוד היו הסודות החיים.",
                          _cands(secret_reads)))
    logs = [(rel, i, ln) for rel, i, ln in p.iter_lines(code) if LOG_CALL.search(ln)
            and re.search(r"(body|payload|message|phone|mail|user|lead|name|text|data)", ln, re.I)]
    if logs:
        tasks.append(Task("ג-logs", "ג", ["E1", "D1"],
                          "מה בדיוק נכנס ליומן? טלפון, מייל, שם, תוכן שיחה, טוקן? יש helper לרדקציה?",
                          "היומן של נועם כתב טלפון מלא ותוכן שיחה בכל תור - בניגוד לשאר אותו קובץ, שבו המיסוך כן קיים.",
                          _cands(logs)))
    paid = [(rel, i, ln) for rel, i, ln in p.iter_lines(code) if PAID_API.search(ln)]
    if paid:
        tasks.append(Task("ד-cost", "ד", ["C1", "F4"],
                          "מה שעולה כסף או ששולח משהו: מי יכול להפעיל אותו בלי אימות, ובכמה? "
                          "יש תקרה על קצב וגם על גודל בקשה?",
                          "בוט הטלגרם הריץ תמלול, שני מודלים ומייל לכל מי שמצא אותו, בלי הגבלה.",
                          _cands(paid)))
    llm_files = [rel for rel in code if LLM_CALL.search(p.text(rel))]
    llm = [(rel, i, ln) for rel, i, ln in p.iter_lines(code) if LLM_CALL.search(ln) or PROMPT_SYSTEM.search(ln)]
    llm += [(rel, i, ln) for rel, i, ln in p.iter_lines(llm_files) if PROMPT_INJECT_VAR.search(ln)]
    if llm:
        tasks.append(Task("ה-prompts", "ה", ["F1", "F2"],
                          "כל מחרוזת שנכנסת לפרומפט: מי כתב אותה, ובאיזה תפקיד היא נוחתת (system או messages)? "
                          "כלים שהמודל מפעיל - ברשימת-היתר ומאומתים בשרת? פעולה בלתי-הפיכה דורשת אדם?",
                          "בנועם הקשר משיחות קודמות של הליד הוזרק למקום של ההוראות.",
                          _cands(llm)))
    html_files = code + [r for r in p.files if p.ext(r) in (".html", ".jinja", ".j2", ".hbs") and not TEST_PATH.search(r)]
    html = [(rel, i, ln) for rel, i, ln in p.iter_lines(html_files) if RAW_HTML.search(ln) or HTML_FROM_REQUEST.search(ln)
            or re.search(r"<(?:div|p|a|td|li|span|h\d)[^>]*>\s*['\"]?\s*\+|\$\{[^}]+\}\s*</", ln)]
    if html:
        tasks.append(Task("ה-html", "ה", ["C4"],
                          "כל HTML (דף או מייל) שמורכב מתוכן שמשתמש או מודל שולטים בו - עובר escape?",
                          "בסטודיו שם-תצוגה שהלקוחה בוחרת נכנס בלי סינון למייל למנטור.",
                          _cands(html)))
    gates = [(rel, i, ln) for rel, i, ln in p.iter_lines(code) if GATE_CODE.search(ln) or SIG_TOKENS.search(ln)]
    if gates:
        tasks.append(Task("ז-gates", "ז", ["—"],
                          "לכל שער: יש בדיקה שנכשלת כשמסירים אותו? הוא אוכף, או במצב דיווח? "
                          "/health מדווח את מצב האכיפה ושיעור הדחיות?",
                          "תיקון שסגר 8 מתוך 31 פונקציות 'עבר' כי השומר בדק רשימה קשיחה.",
                          _cands(gates)))
    return tasks


# --------------------------------------------------------------------------
# סיכונים שהוחלט לקבל
# --------------------------------------------------------------------------

def load_accepted(p: Project, path: str | None) -> tuple[list[dict], list[str]]:
    cand = path or os.path.join(p.git_top or p.root, ".security-accepted.json")
    if not os.path.isfile(cand):
        return [], []
    try:
        with open(cand, encoding="utf-8") as f:
            data = json.load(f)
    except (OSError, json.JSONDecodeError) as e:
        return [], [f"קובץ הסיכונים המקובלים לא קריא ({type(e).__name__}) - אף סיכון לא הוחרג"]
    rules, warn = [], []
    for n, a in enumerate(data.get("accepted", []), 1):
        missing = [k for k in ("reason", "decided") if not a.get(k)]
        if missing:
            warn.append(f"סיכון מקובל #{n} חסר {', '.join(missing)} - לא הוחרג")
            continue
        if not (a.get("key") or a.get("detector")):
            warn.append(f"סיכון מקובל #{n} בלי key או detector - לא הוחרג")
            continue
        rules.append(a)
    return rules, warn


def _accepted_match(f: Finding, rules: list[dict]) -> dict | None:
    for a in rules:
        if a.get("key") and a["key"] == f.key:
            return a
        if a.get("detector") and a["detector"] == f.detector and fnmatch.fnmatch(f.file, a.get("file", "*")):
            return a
    return None


# --------------------------------------------------------------------------
# הרכבת התוצאה
# --------------------------------------------------------------------------

def scan(root: str, out_dir: str, external: bool, history: bool, accepted_path: str | None,
         want_semgrep: bool) -> dict:
    p = Project(root)
    p.load()
    findings: list[Finding] = []
    checked: dict[str, list[str]] = {k: [] for k in FAMILIES}
    not_checked: dict[str, list[str]] = {k: [] for k in FAMILIES}

    for det_id, fam, what, fn in DETECTORS:
        try:
            res = fn(p)
        except Exception as e:  # גלאי שקרס אינו "לא מצא" - הוא "לא נבדק"
            not_checked[fam].append(f"{what} - הגלאי קרס ({type(e).__name__})")
            continue
        findings.extend(res)
        checked[fam].append(what)

    if not p.git["is_repo"]:
        not_checked["ב"].append("קובצי .env בגיט - התיקייה אינה ריפו גיט")

    tools = {}
    if external:
        for name, runner, fams in (("gitleaks", lambda: run_gitleaks(p, history), ["ב"]),
                                   ("osv-scanner", lambda: run_osv(p), ["ו"]),
                                   ("semgrep", lambda: run_semgrep(p) if want_semgrep else
                                    ([], {"ran": False, "reason": "דולג (--no-semgrep)"}), ["א", "ה"])):
            try:
                res, status = runner()
            except Exception as e:
                res, status = [], {"ran": False, "reason": f"{name} קרס ({type(e).__name__})"}
            tools[name] = status
            findings.extend(res)
            for fam in fams:
                (checked if status.get("ran") else not_checked)[fam].append(
                    f"{name}" + (f" ({status.get('mode')})" if status.get("mode") else "")
                    if status.get("ran") else f"{name} - {status.get('reason')}")
    else:
        for name, fams in (("gitleaks", ["ב"]), ("osv-scanner", ["ו"]), ("semgrep", ["א", "ה"])):
            tools[name] = {"ran": False, "reason": "דולג (--no-external)"}
            for fam in fams:
                not_checked[fam].append(f"{name} - דולג (--no-external)")

    # כפילויות (אותו מפתח משני גלאים) - משאירים את הראשון
    uniq: dict[str, Finding] = {}
    for f in findings:
        uniq.setdefault(f.key, f)
    findings = list(uniq.values())

    rules, warnings = load_accepted(p, accepted_path)
    open_f, accepted = [], []
    for f in findings:
        a = _accepted_match(f, rules)
        if a:
            accepted.append({**asdict(f), "accepted_reason": a["reason"], "accepted_on": a["decided"],
                             "accepted_by": a.get("by", ""), "revisit": a.get("revisit", "")})
        else:
            open_f.append(f)
    gl_ignore = os.path.join(p.git_top or p.root, ".gitleaksignore")
    gl_count = 0
    if os.path.isfile(gl_ignore):
        with open(gl_ignore, encoding="utf-8", errors="replace") as fh:
            gl_count = sum(1 for x in fh if x.strip() and not x.startswith("#"))

    tasks = build_tasks(p)
    result = {
        "schema_version": SCHEMA_VERSION,
        "engine_version": ENGINE_VERSION,
        "scanned_at": datetime.now().astimezone().isoformat(timespec="seconds"),
        "project": {"name": p.name, "path": p.root, "git": p.git},
        "scope": {"files": len(p.files), "code_files": len(p.code_files()),
                  "ignore_patterns": len(p.ignore_globs)},
        "tools": tools,
        "checked": checked,
        "not_checked": not_checked,
        "findings": [asdict(f) for f in sorted(open_f, key=lambda f: (SEV_RANK[f.severity], f.family, f.file, f.line))],
        "accepted_risks": accepted,
        "gitleaksignore_entries": gl_count,
        "judgment_tasks": [asdict(t) for t in tasks],
        "reviews": [],
        "warnings": p.warnings + warnings,
    }
    finalize(result)
    write_outputs(result, out_dir)
    return result


def finalize(result: dict) -> None:
    """מחשב את מצב המשפחות ואת הסיכום. רץ גם אחרי merge."""
    fams = {}
    for k, meta in FAMILIES.items():
        fs = [f for f in result["findings"] if f["family"] == k]
        pending = [t["id"] for t in result["judgment_tasks"] if t["family"] == k and t["status"] == "ממתין"]
        nc = result["not_checked"].get(k, []) + [
            f"משימה {t['id']} - {t['status']}" for t in result["judgment_tasks"]
            if t["family"] == k and t["status"] == "לא נבדק"]
        if fs:
            status = "נמצאו ממצאים"
        elif pending:
            status = "ממתין לבדיקת סוכן"
        elif nc:
            status = "נבדק חלקית"
        elif result["checked"].get(k):
            status = "נבדק, לא נמצא"
        else:
            status = "לא נבדק"
        fams[k] = {"name": meta["name"], "status": status, "findings": len(fs),
                   "by_severity": {s: sum(1 for f in fs if f["severity"] == s) for s in SEVERITIES},
                   "checked": result["checked"].get(k, []), "not_checked": nc, "pending_tasks": pending}
    result["families"] = fams
    by_sev = {s: sum(1 for f in result["findings"] if f["severity"] == s) for s in SEVERITIES}
    pending = [t["id"] for t in result["judgment_tasks"] if t["status"] == "ממתין"]
    certain_high = sum(1 for f in result["findings"] if f["severity"] in ("critical", "high")
                       and f["confidence"] != CONF_SUSPECT)
    result["summary"] = {
        "open_findings": len(result["findings"]),
        "by_severity": by_sev,
        "certain_high": certain_high,
        "accepted": len(result["accepted_risks"]),
        "pending_tasks": len(pending),
        "exit_code": 1 if by_sev["critical"] or by_sev["high"] else 0,
    }


def exit_code(result: dict, fail_on: str) -> int:
    """high = כל ממצא קריטי/גבוה, גם חשוד (ברירת מחדל - לאדם ולסוכן).
    certain-high = רק מה שהמכונה הכריעה או שסוכן אישר (ל-CI: חשוד שעוצר את כולם
    הוא שומר שנושך יותר מדי, ומכבים אותו - משפחה ז, הצורה החמישית).
    none = לעולם לא נכשל על ממצאים (רק על תקלה)."""
    if fail_on == "none":
        return 0
    if fail_on == "certain-high":
        return 1 if result["summary"]["certain_high"] else 0
    return result["summary"]["exit_code"]


# --------------------------------------------------------------------------
# פלט
# --------------------------------------------------------------------------

def _md_cell(s) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def render_md(r: dict) -> str:
    g = r["project"]["git"]
    s = r["summary"]
    date = r["scanned_at"][:10]
    lines = [f"# {r['project']['name']} - ביקורת אבטחה ({date})", ""]
    where = f"commit: `{g.get('commit')}`, ענף: `{g.get('branch')}`" if g.get("is_repo") else "לא ריפו גיט"
    lines.append(f"מה נסרק: {r['scope']['files']} קבצים ({r['scope']['code_files']} קובצי קוד), {where}. "
                 f"מנוע {r['engine_version']}.")
    lines.append("")
    sev_line = " · ".join(f"{SEV_HE[k]} {v}" for k, v in s["by_severity"].items() if v) or "אין"
    lines.append(f"**בשורה אחת:** {s['open_findings']} ממצאים פתוחים ({sev_line}), "
                 f"{s['pending_tasks']} משימות ממתינות לבדיקת סוכן, {s['accepted']} סיכונים שהוחלט לקבל.")
    lines.append("")
    lines.append("> כל ממצא כאן **הוסק מקוד** - לא אומת חי. 'ודאי' = המכונה הכריעה; 'חשוד' = דפוס שנראה כמו "
                 "הכשל, וסוכן צריך לאשר. ערכי סודות לעולם אינם מוצגים.")
    lines += ["", "## מצב לפי משפחה", "", "| משפחה | מצב | ממצאים | ממתין לסוכן | לא נבדק |", "|---|---|---|---|---|"]
    for k, fm in r["families"].items():
        lines.append(f"| {k} - {fm['name']} | {fm['status']} | {fm['findings']} | "
                     f"{len(fm['pending_tasks'])} | {_md_cell('; '.join(fm['not_checked'])) or '-'} |")
    lines += ["", "## ממצאים", ""]
    if r["findings"]:
        lines += ["| ID | חומרה | ודאות | משפחה | סעיף | מה נמצא | ראיה | תיקון מוצע |", "|---|---|---|---|---|---|---|---|"]
        for n, f in enumerate(r["findings"], 1):
            loc = f"`{f['file']}:{f['line']}`" if f["line"] else f"`{f['file']}`"
            ev = f" - {_md_cell(f['evidence'])}" if f["evidence"] else ""
            lines.append(f"| S{n:02d} | {SEV_HE[f['severity']]} | {f['confidence']} | {f['family']} | {f['item']} | "
                         f"{_md_cell(f['title'])} | {loc}{ev} | {_md_cell(f['fix'])} |")
    else:
        lines.append("אין ממצאים פתוחים.")
    probes = [f for f in r["findings"] if f.get("probe")]
    if probes:
        lines += ["", "## רשימת בדיקות חיות", "", "| מה | בדיקה | איפה בקוד |", "|---|---|---|"]
        for f in probes:
            lines.append(f"| {_md_cell(f['title'])} | {_md_cell(f['probe'])} | `{f['file']}:{f['line']}` |")
    tasks = [t for t in r["judgment_tasks"] if t["status"] == "ממתין"]
    lines += ["", "## ממתין לבדיקת סוכן", ""]
    if tasks:
        lines.append("ההוראות המלאות, כולל המקומות בקוד: `review-brief.md` שליד הדוח.")
        lines.append("")
        for t in tasks:
            lines.append(f"- **{t['id']}** ({len(t['candidates'])} מקומות): {t['question']}")
    else:
        lines.append("אין.")
    if r["reviews"]:
        lines += ["", "## מה סוכן בדק", ""]
        for rv in r["reviews"]:
            lines.append(f"- **{rv['task_id']}** - {rv['verdict']} ({rv.get('reviewer', '')}, {rv.get('reviewed_at', '')})"
                         + (f": {rv['notes']}" if rv.get("notes") else ""))
    lines += ["", "## מה נבדק ונמצא תקין", ""]
    for k, fm in r["families"].items():
        clean = fm["checked"] if not fm["findings"] else []
        if clean:
            lines.append(f"- **{k}:** " + "; ".join(clean))
    lines += ["", "## מה לא נבדק ולמה", ""]
    any_nc = False
    for k, fm in r["families"].items():
        for x in fm["not_checked"]:
            lines.append(f"- **{k}:** {x}")
            any_nc = True
    lines.append("- **תמיד:** בדיקה חיה (קריאות אמיתיות לשירות), הגדרות אצל ספק האירוח, והיסטוריית הגיט "
                 "(אלא אם הורץ עם --history).")
    if not any_nc:
        pass
    if r["accepted_risks"] or r.get("gitleaksignore_entries"):
        lines += ["", "## סיכונים שהוחלט לקבל", ""]
        for a in r["accepted_risks"]:
            lines.append(f"- {a['title']} (`{a['file']}`) - {a['accepted_reason']} "
                         f"(הוחלט {a['accepted_on']}{', ' + a['accepted_by'] if a.get('accepted_by') else ''})")
        if r.get("gitleaksignore_entries"):
            lines.append(f"- `.gitleaksignore`: {r['gitleaksignore_entries']} שורות שסורק הסודות מדלג עליהן.")
    if r["warnings"]:
        lines += ["", "## אזהרות", ""] + [f"- {w}" for w in r["warnings"]]
    lines += ["", "## כלים", ""]
    for name, st in r["tools"].items():
        lines.append(f"- {name}: " + (f"רץ ({st.get('version', '')}{', ' + st['mode'] if st.get('mode') else ''})"
                                      if st.get("ran") else f"לא רץ - {st.get('reason')}"))
    return "\n".join(lines) + "\n"


def render_brief(r: dict, audit_path: str) -> str:
    tasks = [t for t in r["judgment_tasks"] if t["status"] == "ממתין"]
    L = [f"# בדיקת סוכן - {r['project']['name']} ({r['scanned_at'][:10]})", "",
         "הבדיקות המכניות רצו. מה שנשאר דורש **קריאת קוד ושיקול דעת** - וזה החלק שבו נמצאו כל 13 "
         "הממצאים הקריטיים והגבוהים של ביקורת 09/2026.", "",
         "## איך עונים", "",
         "1. לכל משימה: לקרוא את המקומות שברשימה **ואת הקוד שסביבם** (הרשימה היא נקודת פתיחה, לא גבול).",
         "2. לענות בקובץ JSON אחד, בפורמט שבסוף.",
         "3. להריץ:", "", "```bash",
         f"python3 \"{os.path.abspath(__file__)}\" merge \"{audit_path}\" review.json", "```", "",
         "**כללים:** לעולם לא להעתיק ערך של סוד לתשובה. 'לא נבדק' עדיף על ניחוש - ולצרף למה. "
         "חומרה: קריטי (נתונים/כסף חשופים בלי אימות) · גבוה (שער שנפתח בתנאי סביר) · בינוני · נמוך.", ""]
    for t in tasks:
        L += [f"## {t['id']} - משפחה {t['family']} ({FAMILIES[t['family']]['name']})", "",
              f"**השאלה:** {t['question']}", "", f"**למה:** {t['why']}", "",
              f"**סעיפי הצ'קליסט:** {', '.join(t['items'])}", "", "**איפה להתחיל:**", ""]
        L += [f"- `{c['file']}:{c['line']}` - `{c['snippet']}`" for c in t["candidates"]]
        L.append("")
    if not tasks:
        L.append("אין משימות ממתינות.")
    L += ["## פורמט התשובה", "", "```json", json.dumps({
        "reviewer": "<מי בדק>", "reviewed_at": "YYYY-MM-DD",
        "reviews": [{"task_id": tasks[0]["id"] if tasks else "<id>", "verdict": "ממצא",
                     "notes": "מה נבדק ואיך",
                     "findings": [{"title": "...", "severity": "high", "file": "src/x.py", "line": 12,
                                   "item": "B4", "fix": "...", "probe": "GET /x/123 כמשתמש אחר ← 403"}]},
                    {"task_id": "<id>", "verdict": "תקין", "notes": "איפה ההגנה"},
                    {"task_id": "<id>", "verdict": "לא נבדק", "notes": "למה"}]}, ensure_ascii=False, indent=2),
          "```", ""]
    return "\n".join(L)


def write_outputs(result: dict, out_dir: str) -> None:
    os.makedirs(out_dir, exist_ok=True)
    ap = os.path.join(out_dir, "audit.json")
    with open(ap, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    with open(os.path.join(out_dir, "audit.md"), "w", encoding="utf-8") as f:
        f.write(render_md(result))
    with open(os.path.join(out_dir, "review-brief.md"), "w", encoding="utf-8") as f:
        f.write(render_brief(result, ap))


# --------------------------------------------------------------------------
# merge - הכנסת התשובות של הסוכן
# --------------------------------------------------------------------------

VERDICTS = {"ממצא": "ממצא", "finding": "ממצא", "תקין": "תקין", "ok": "תקין",
            "לא נבדק": "לא נבדק", "not_checked": "לא נבדק"}


class ReviewError(ValueError):
    pass


def merge(audit_path: str, review_path: str) -> dict:
    with open(audit_path, encoding="utf-8") as f:
        result = json.load(f)
    with open(review_path, encoding="utf-8") as f:
        review = json.load(f)
    if result.get("schema_version") != SCHEMA_VERSION:
        raise ReviewError(f"audit.json בגרסת סכמה {result.get('schema_version')}, המנוע מכיר {SCHEMA_VERSION}")
    tasks = {t["id"]: t for t in result["judgment_tasks"]}
    reviews = review.get("reviews")
    if not isinstance(reviews, list) or not reviews:
        raise ReviewError("אין רשימת reviews בקובץ התשובה")
    new_findings = []
    for rv in reviews:
        tid = rv.get("task_id")
        if tid not in tasks:
            raise ReviewError(f"משימה לא מוכרת: {tid!r}")
        verdict = VERDICTS.get(str(rv.get("verdict", "")).strip().lower()) or VERDICTS.get(str(rv.get("verdict", "")).strip())
        if not verdict:
            raise ReviewError(f"{tid}: verdict חייב להיות ממצא / תקין / לא נבדק")
        if verdict == "ממצא" and not rv.get("findings"):
            raise ReviewError(f"{tid}: verdict 'ממצא' בלי findings")
        if verdict == "לא נבדק" and not rv.get("notes"):
            raise ReviewError(f"{tid}: 'לא נבדק' חייב לומר למה (notes)")
        for fd in rv.get("findings", []) if verdict == "ממצא" else []:
            sev = SEV_FROM_ANY.get(str(fd.get("severity", "")).strip().lower()) or SEV_FROM_ANY.get(str(fd.get("severity", "")).strip())
            if not sev:
                raise ReviewError(f"{tid}: חומרה לא מוכרת {fd.get('severity')!r}")
            if not fd.get("title") or not fd.get("file"):
                raise ReviewError(f"{tid}: לכל ממצא נדרשים title ו-file")
            f = Finding(f"review:{tid}", tasks[tid]["family"], fd.get("item") or ",".join(tasks[tid]["items"]),
                        sev, CONF_REVIEWED, redact(str(fd["title"])), str(fd["file"]), int(fd.get("line") or 0),
                        redact(str(fd.get("evidence", ""))), redact(str(fd.get("fix", ""))),
                        redact(str(fd.get("probe", ""))), source="review")
            new_findings.append(asdict(f.finalize(f"{fd['title']}|{fd.get('line')}")))
        tasks[tid]["status"] = {"ממצא": "נבדק - נמצא", "תקין": "נבדק - תקין", "לא נבדק": "לא נבדק"}[verdict]
        result["reviews"].append({"task_id": tid, "verdict": verdict, "notes": redact(str(rv.get("notes", ""))),
                                  "reviewer": review.get("reviewer", ""), "reviewed_at": review.get("reviewed_at", "")})
    existing = {f["key"] for f in result["findings"]}
    result["findings"] += [f for f in new_findings if f["key"] not in existing]
    result["findings"].sort(key=lambda f: (SEV_RANK[f["severity"]], f["family"], f["file"], f["line"]))
    finalize(result)
    write_outputs(result, os.path.dirname(os.path.abspath(audit_path)))
    return result


# --------------------------------------------------------------------------
# CLI
# --------------------------------------------------------------------------

def default_out(root: str) -> str:
    p = Project(root)
    rc, top = p._git("rev-parse", "--show-toplevel")
    name = os.path.basename(top.strip()) if rc == 0 and top.strip() else os.path.basename(os.path.abspath(root))
    sub = os.path.relpath(os.path.abspath(root), top.strip()) if rc == 0 and top.strip() else "."
    if sub != ".":
        name += "__" + sub.replace(os.sep, "_")
    return os.path.join(os.path.expanduser("~/Documents/security-audit"), name)


def main(argv: list[str] | None = None) -> int:
    argv = list(sys.argv[1:] if argv is None else argv)
    if argv and argv[0] not in ("scan", "merge", "-h", "--help", "--version"):
        argv.insert(0, "scan")
    ap = argparse.ArgumentParser(prog="audit.py", description="מנוע ביקורת אבטחה - שבע משפחות הכשל")
    ap.add_argument("--version", action="version", version=f"audit.py {ENGINE_VERSION} (schema {SCHEMA_VERSION})")
    sub = ap.add_subparsers(dest="cmd", required=True)
    s = sub.add_parser("scan", help="סריקת פרויקט")
    s.add_argument("path")
    s.add_argument("--out", help="תיקיית התוצרים (ברירת מחדל: ~/Documents/security-audit/<פרויקט>)")
    s.add_argument("--no-external", action="store_true", help="בלי gitleaks / osv-scanner / semgrep")
    s.add_argument("--no-semgrep", action="store_true", help="בלי semgrep (האיטי מבין השלושה)")
    s.add_argument("--history", action="store_true", help="gitleaks על כל היסטוריית הגיט")
    s.add_argument("--accepted", help="קובץ סיכונים מקובלים (ברירת מחדל: .security-accepted.json בשורש)")
    s.add_argument("--fail-on", choices=("high", "certain-high", "none"), default="high",
                   help="מתי קוד היציאה 1 (ברירת מחדל: כל ממצא קריטי/גבוה; ב-CI: certain-high)")
    s.add_argument("--quiet", action="store_true")
    m = sub.add_parser("merge", help="הכנסת תשובות הסוכן לתוצאה")
    m.add_argument("audit_json")
    m.add_argument("review_json")
    args = ap.parse_args(argv)

    if args.cmd == "merge":
        try:
            r = merge(args.audit_json, args.review_json)
        except (OSError, json.JSONDecodeError, ReviewError) as e:
            print(f"❌ merge נכשל: {e}", file=sys.stderr)
            return 2
        print(f"✅ התשובות נכנסו. ממצאים פתוחים: {r['summary']['open_findings']}, "
              f"משימות ממתינות: {r['summary']['pending_tasks']}")
        return r["summary"]["exit_code"]

    if not os.path.isdir(args.path):
        print(f"❌ אין תיקייה כזו: {args.path}", file=sys.stderr)
        return 2
    out = args.out or default_out(args.path)
    try:
        r = scan(args.path, out, not args.no_external, args.history, args.accepted, not args.no_semgrep)
    except Exception as e:
        print(f"❌ המנוע נכשל: {type(e).__name__}: {e}", file=sys.stderr)
        return 2
    if not args.quiet:
        s = r["summary"]
        print(f"🔍 {r['project']['name']}: {s['open_findings']} ממצאים פתוחים "
              f"(קריטי {s['by_severity']['critical']}, גבוה {s['by_severity']['high']}, "
              f"בינוני {s['by_severity']['medium']}, נמוך {s['by_severity']['low']}), "
              f"{s['pending_tasks']} משימות לבדיקת סוכן.")
        for k, fm in r["families"].items():
            print(f"   {k} {fm['name']}: {fm['status']}")
        nc = [t for t, st in r["tools"].items() if not st.get("ran")]
        if nc:
            print(f"⚠️ לא רצו: {', '.join(nc)} - מה שהם בודקים סומן 'לא נבדק'.")
        print(f"📄 {os.path.join(out, 'audit.md')}")
    return exit_code(r, args.fail_on)


if __name__ == "__main__":
    sys.exit(main())
